#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maxOperations(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int left = 0, right = (int)nums.size() - 1;
        int ops = 0;
        while (left < right) {
            int s = nums[left] + nums[right];
            if (s == k) {
                ops++;
                left++;
                right--;
            } else if (s < k) {
                left++;
            } else {
                right--;
            }
        }
        return ops;
    }
};

import java.util.*;

class Solution {
    public int maxOperations(int[] nums, int k) {
        Arrays.sort(nums);
        int left = 0, right = nums.length - 1;
        int ops = 0;
        while (left < right) {
            int s = nums[left] + nums[right];
            if (s == k) {
                ops++;
                left++;
                right--;
            } else if (s < k) {
                left++;
            } else {
                right--;
            }
        }
        return ops;
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var maxOperations = function(nums, k) {
    nums.sort((a, b) => a - b);
    let left = 0, right = nums.length - 1;
    let ops = 0;
    while (left < right) {
        const s = nums[left] + nums[right];
        if (s === k) {
            ops++;
            left++;
            right--;
        } else if (s < k) {
            left++;
        } else {
            right--;
        }
    }
    return ops;
};
